"""Keep developer notes and dependency bumps out of GitHub Release notes."""
import importlib.util
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("release_notes", Path(__file__).with_name("release-notes.py"))
MODULE = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(MODULE)

CHANGELOG = """# WH3 Mod Manager changelog

Release entries are generated by Sampo from `.sampo/changesets` when preparing a release PR.

## 0.4.0 — 2026-11-01

### Added

- [abc1234](https://example.invalid) Add a feature.
  Its description continues here.

### Patch changes

- Updated dependencies: wh3-core@0.4.0

## 0.3.10 — 2026-10-20

### Fixed

- Fix a bug.

### Patch changes

- Updated dependencies: wh3-core@0.3.10

## 0.3.1 — 2026-10-02

### Fixed

- Fix an older bug.
"""


class ReleaseNotesTests(unittest.TestCase):
    def test_entry_without_header_and_dependency_bumps(self):
        self.assertEqual(
            MODULE.notes(CHANGELOG, "v0.4.0"),
            "### Added\n\n- [abc1234](https://example.invalid) Add a feature.\n"
            "  Its description continues here.\n",
        )

    def test_version_is_matched_exactly(self):
        self.assertEqual(MODULE.notes(CHANGELOG, "v0.3.1"), "### Fixed\n\n- Fix an older bug.\n")
        self.assertEqual(MODULE.notes(CHANGELOG, "v0.3.10"), "### Fixed\n\n- Fix a bug.\n")

    def test_missing_or_empty_entry_is_rejected(self):
        with self.assertRaisesRegex(ValueError, "no entry for 0.5.0"):
            MODULE.notes(CHANGELOG, "v0.5.0")
        with self.assertRaisesRegex(ValueError, "no release notes"):
            MODULE.notes("## 0.6.0 — 2026-12-01\n\n### Patch changes\n\n- Updated dependencies: wh3-core@0.6.0\n", "v0.6.0")

    def test_every_released_entry_has_notes(self):
        changelog = (ROOT / MODULE.CHANGELOG).read_text(encoding="utf-8")
        for version in ["v0.2.0", "v0.3.0", "v0.3.1", "v0.3.2"]:
            notes = MODULE.notes(changelog, version)
            self.assertNotIn("Updated dependencies", notes)
            self.assertNotIn("Release entries are generated", notes)


if __name__ == "__main__":
    unittest.main()
